-- 8. Thu / chi quy trong ca

-- Tien ket du kien = tien dau ca + tien mat ban duoc + thu - chi (giong cach app tinh); tien dem thuc te = du kien + chenh lech
UPDATE cash_shifts c SET c.expected_amount = c.opening_amount
  + COALESCE((SELECT SUM(o.total) FROM orders o WHERE o.cash_shift_id = c.cash_shift_id AND o.status = 'paid' AND o.payment_method = 'cash'), 0)
  + COALESCE((SELECT SUM(t.amount) FROM cash_transactions t WHERE t.cash_shift_id = c.cash_shift_id AND t.transaction_type = 'cash_in'), 0)
  - COALESCE((SELECT SUM(t.amount) FROM cash_transactions t WHERE t.cash_shift_id = c.cash_shift_id AND t.transaction_type = 'cash_out'), 0)
WHERE c.closed_at IS NOT NULL AND c.cash_shift_id > @cb;
UPDATE cash_shifts SET closing_amount = expected_amount + difference WHERE closed_at IS NOT NULL AND cash_shift_id > @cb;

